begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir helpers/fms_visit_assignment_fixture.psql
create temporary table denied_work(request jsonb);
grant all on denied_work to authenticated;
insert into denied_work values(jsonb_build_object('kind','stage_form','instanceStageId',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='call')),'formTemplateId',(select id from visit_assignment_fixture where name='form'),'answers',jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='c')),'outcome','','remark','','checklist','{}'::jsonb));
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='e_auth'),true);
select throws_ok($$select preview_fms_work_transition(request) from denied_work$$,'42501','FMS work is not available to your account','ordinary employee cannot preview another employee assignment');
select throws_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),'[]',null) from denied_work$$,'42501',null,'ordinary employee cannot bypass the UI and complete another assignment');
reset role;
update user_profiles set is_login_enabled=false where id=(select id from visit_assignment_fixture where name='b');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
set local role authenticated;
select throws_ok($$select preview_fms_work_transition(request) from denied_work$$,'42501',null,'inactive assigned employee cannot preview work');
reset role;
insert into tenants(name,slug) values('Other synthetic tenant','fms-denial-other');
insert into branches(tenant_id,name,code) select id,'Other branch','OTHER' from tenants where slug='fms-denial-other';
insert into departments(tenant_id,branch_id,name,code) select b.tenant_id,b.id,'Other department','OTHER' from branches b join tenants t on t.id=b.tenant_id where t.slug='fms-denial-other';
update user_profiles set tenant_id=(select id from tenants where slug='fms-denial-other'),branch_id=(select b.id from branches b join tenants t on t.id=b.tenant_id where t.slug='fms-denial-other'),department_id=(select d.id from departments d join tenants t on t.id=d.tenant_id where t.slug='fms-denial-other') where id=(select id from visit_assignment_fixture where name='e');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='e_auth'),true);
set local role authenticated;
select throws_ok($$select preview_fms_work_transition(request) from denied_work$$,'42501',null,'cross-tenant employee cannot preview work');
select throws_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),'[]',null) from denied_work$$,'42501',null,'cross-tenant direct completion is denied');
reset role;
select ok(not has_function_privilege('anon','preview_fms_work_transition(jsonb,jsonb)','execute'),'anonymous preview denied');
select ok(not has_function_privilege('service_role','apply_fms_initial_handoffs(uuid,uuid,jsonb)','execute'),'service-role cannot directly call private starting intent writer');
select is((select count(*)::integer from form_submissions where linked_record_id=(select (request->>'instanceStageId')::uuid from denied_work)),0,'denials leave the work form unsaved');
select * from finish();
rollback;
